pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
    if expected != self.revision {
        return Outcome {
            accepted: false,
            revision: self.revision,
            violations: None,
            certificate: self.certificate(query),
        };
    }

    self.tx_counter += 1;
    let stamp = self.tx_counter;

    // Snapshot the committed values of every task and group touched by
    // this proposal: pin protection is judged against the state at the
    // beginning of the transaction.
    let mut edited_tasks: Vec<usize> = Vec::new();
    let mut quota_groups: Vec<usize> = Vec::new();
    for edit in edits {
        match edit {
            Edit::Move(task, _) | Edit::Weight(task, _) | Edit::Class(task, _)
            | Edit::Bind(task, _) | Edit::Pin(task, _) => {
                if self.task_mark[*task] != stamp {
                    self.task_mark[*task] = stamp;
                    edited_tasks.push(*task);
                }
            }
            Edit::Quota(group, _) => {
                if self.quota_mark[*group] != stamp {
                    self.quota_mark[*group] = stamp;
                    quota_groups.push(*group);
                }
            }
            Edit::Budget(_, _) | Edit::Cap(_, _) => {}
        }
    }
    let mut task_snaps: Vec<(usize, TaskSnap)> = Vec::with_capacity(edited_tasks.len());
    for &task in &edited_tasks {
        task_snaps.push((
            task,
            TaskSnap {
                template: self.task_template[task],
                group: self.task_group[task],
                weight: self.task_weight[task],
                class: self.task_class[task],
                pinned: self.task_pinned[task],
            },
        ));
    }
    let mut quota_snaps: HashMap<usize, (u64, u32)> = HashMap::new();
    for &group in &quota_groups {
        quota_snaps.insert(group, (self.group_quota[group], self.group_pins[group]));
    }

    // Apply the proposal.
    let mut undo: Vec<Undo> = Vec::with_capacity(edits.len());
    let mut touched: Vec<usize> = Vec::new();
    for edit in edits {
        match edit {
            Edit::Move(task, group) => {
                self.touch(self.task_group[*task], &mut touched);
                let old = self.task_group[*task];
                self.apply_move(*task, *group);
                self.touch(*group, &mut touched);
                undo.push(Undo::Move(*task, old));
            }
            Edit::Weight(task, weight) => {
                self.touch(self.task_group[*task], &mut touched);
                let old = self.task_weight[*task];
                self.apply_weight(*task, *weight);
                undo.push(Undo::Weight(*task, old));
            }
            Edit::Class(task, class) => {
                self.touch(self.task_group[*task], &mut touched);
                let old = self.task_class[*task];
                self.apply_class(*task, *class);
                undo.push(Undo::Class(*task, old));
            }
            Edit::Bind(task, template) => {
                self.touch(self.task_group[*task], &mut touched);
                let old = self.task_template[*task];
                self.apply_bind(*task, *template);
                undo.push(Undo::Bind(*task, old));
            }
            Edit::Pin(task, pinned) => {
                self.touch(self.task_group[*task], &mut touched);
                let old = self.task_pinned[*task];
                self.apply_pin(*task, *pinned);
                undo.push(Undo::Pin(*task, old));
            }
            Edit::Quota(group, quota) => {
                self.touch(*group, &mut touched);
                let old = self.group_quota[*group];
                self.apply_quota(*group, *quota);
                undo.push(Undo::Quota(*group, old));
            }
            Edit::Budget(group, budget) => {
                self.touch(*group, &mut touched);
                let old = self.group_budget[*group];
                self.apply_budget(*group, *budget);
                undo.push(Undo::Budget(*group, old));
            }
            Edit::Cap(node, capacity) => {
                let old = self.caps[*node];
                self.apply_cap(*node, *capacity);
                undo.push(Undo::Cap(*node, old));
            }
        }
    }
